entries[5697] = { ["name"] = "Tablet of Healing Totem", ["text"] = "Classes: Shaman\nRequires Level 6\nUse: Teaches Healing Totem (Rank 1).\nSummons a Healing Stream Totem with 5 health at the feet of the caster for 5 min that heals party members within 30 yards for [( 1 + (Spell power * 0.0827) * (( 1 * 1 )))] every 2 seconds [ Glyph of Healing Stream Totem : and increases the Fire, Frost, and Nature resistance of party and raid members within 30 yards by [( 85 <= 70 ? 85 : ( 85 <= 80 ? 85 + ( 85 - 70) * 5 : 85 + ( 85 - 70) * 5 + ( 85 - 80) * 7))] ].\nSell Price:" }
entries[5698] = { ["name"] = "Tablet of Lightning Shield", ["text"] = "Classes: Shaman\nRequires Level 8\nUse: Teaches Lightning Shield (Rank 1).\nThe caster is surrounded by 3 balls of lightning. When a spell, melee or ranged attack hits the caster, the attacker will be struck for 12 Nature damage. This expends one lightning ball [ Glyph of Lightning Shield : but will not reduce the number of charges below 3 ]. Only one ball will fire every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time. (3.5s cooldown)\nSell Price:" }
